{"taskId":"scene-r7-a-bark-retry1","stage":"A","purpose":"树皮与材质照明分离","parents":["scene-r7-a-bark"],"sourceRevision":"04fb5a3a9de8c3e9c2a408fa4355e55e2f5ff21f","sceneSha256":"4d00caf13362036ad338db65a3eae2782a891157d7a25452baff170bf61a8ecc","specification":"The actual bark3 texture still contains photographed shading; scalar1.20 is display compensation, not measured albedo, and bark looks smooth/painted. Implement robust low-frequency shading separation or multi-view-consistent diffuse fitting with confidence and seam handling; do not hallucinate high-frequency relief or add RGB as normalTexture. Pure numpy module operates on linear RGB patch plus foreground confidence and controlled illumination bounds; preserve observed vertical detail, guard near-black/chroma instability. Explain exact UV/colour-space integration and cross-renderer rejection controls. Compare actual WebGL and Cycles images, including13 discrepancy; unknown back side remains explicit.","source":[{"path":"infra/reconstruction/build_captured_bark.py","originalFileSha256":"4f27073417cd2ca4adb9715693bdad70109731498eaa01d723647889ed1216b2","lines":[1,47],"code":""""Bake a cylindrical photograph-informed bark sample onto the existing native stem.

Camera 01 provides the visible side. The reverse side repeats the nearest visible
bark appearance. The high fork is extrapolated from the last clear lower-stem row.
"""
import json
from pathlib import Path
import sys
import numpy as np
from PIL import Image
from scipy.ndimage import map_coordinates, gaussian_filter

stem_file,photo_file,projection_file,output=map(Path,sys.argv[1:])
vertices=np.asarray(json.loads(stem_file.read_text())['vertices']).reshape(-1,24,3)
matrix=np.asarray(json.loads(projection_file.read_text())['01']).reshape(4,4,order='F')
photo=np.asarray(Image.open(photo_file).convert('RGB'),dtype=float)/255
centres=vertices.mean(axis=1)
heights=centres[:,2]
height,width=1024,512
samples=np.linspace(0,1,height)
u=np.linspace(0,1,width)
idx=np.clip(u*23,0,22.999999); left=idx.astype(int); blend=idx-left
coords=[]
for v in samples:
 z=min(4.32,v*heights[-1])
 k=np.clip(np.searchsorted(heights,z)-1,0,len(heights)-2)
 t=(z-heights[k])/(heights[k+1]-heights[k])
 ring=vertices[k]*(1-t)+vertices[k+1]*t
 points=ring[left]*(1-blend[:,None])+ring[left+1]*blend[:,None]
 # Project the physical lower stem to the capture. Mirror the unseen cylinder
 # angles into the visible bark area rather than sampling the surrounding lawn.
 px=np.column_stack((points[:,0],points[:,2],-points[:,1],np.ones(width)))@matrix.T
 x=(px[:,0]/px[:,3]+1)*512
 y=(1-px[:,1]/px[:,3])*384
 centre=np.append([centres[k,0],z,-centres[k,1]],1)@matrix.T
 cx=(centre[0]/centre[3]+1)*512
 x=cx+(x-cx)*.72
 coords.append((x,y))
coords=np.array(coords)
rgb=np.stack([map_coordinates(photo[:,:,c],[coords[:,1,:],coords[:,0,:]],order=1,mode='nearest') for c in range(3)],axis=-1)
assert rgb.shape == (height, width, 3), 'Projected bark must retain both texture dimensions'
# Approximate albedo compensation for the fixed display illumination. The texture
# remains diffuse; this multiplier is recorded, not treated as measured reflectance.
linear=np.where(rgb<=.04045,rgb/12.92,((rgb+.055)/1.055)**2.4)
linear=np.clip(linear*1.20,0,.88)
rgb=np.where(linear<=.0031308,12.92*linear,1.055*linear**(1/2.4)-.055)
Image.fromarray((rgb[::-1]*255).astype('uint8')).save(output)"},{"path":"infra/reconstruction/install_captured_bark.py","originalFileSha256":"5137ff8d3969609e7c4046946fde658745e81ff76b55f276b24475a722bf9946","lines":[1,42],"code":""""Install a unique cylindrical bark UV for the photographed foreground trunk."""
from pathlib import Path
import sys,bpy,json,struct
image,asset,*saved = map(Path,sys.argv[sys.argv.index('--')+1:])
o=bpy.data.objects['tree.foreground.trunk']
mesh=o.data
if len(mesh.vertices)!=816:raise ValueError('The source trunk ring topology changed')
material=bpy.data.materials.new('Foreground bark from photograph 01')
material.use_nodes=True
graph=material.node_tree
shader=graph.nodes.get('Principled BSDF')
shader.inputs['Roughness'].default_value=.94
texture=graph.nodes.new('ShaderNodeTexImage')
texture.image=bpy.data.images.load(str(image.resolve()))
if texture.image.size[0] < 128 or texture.image.size[1] < 128:
 raise ValueError('Bark projection lost a texture dimension')
texture.image.pack()
graph.links.new(texture.outputs['Color'],shader.inputs['Base Color'])
# This photograph is diffuse appearance. It contains no tangent-space normal
# measurements, and Blender's exporter cannot turn a Bump node into a valid
# normal texture. Keep the leaf-independent bark roughness and real geometry.
mesh.materials.clear()
mesh.materials.append(material)
height=max(v.co.z for v in mesh.vertices)
for loop,uv in zip(mesh.loops,mesh.uv_layers.active.data):
 v=mesh.vertices[loop.vertex_index]
 uv.uv=(loop.vertex_index%24/23,v.co.z/height)
o['bark_basis']='Photograph 01 projected onto original lower-stem rings; rear repeats observed bark, high fork extrapolated. Diffuse compensation 1.20 is an engineering display estimate; captured lighting remains in the texture. No measured normal map.'
bpy.ops.object.select_all(action='DESELECT')
o.select_set(True);bpy.context.view_layer.objects.active=o
bpy.ops.export_scene.gltf(filepath=str(asset.resolve()),export_format='GLB',
 use_selection=True,export_animations=False,export_cameras=False,export_lights=False,export_extras=True)
raw=asset.read_bytes()
doc=json.loads(raw[20:20+struct.unpack_from('<I',raw,12)[0]])
for exported in doc['materials']:
 if exported.get('normalTexture') is not None:
  raise ValueError('Diffuse bark exported an unexpected normal texture')
 if 'baseColorTexture' not in exported.get('pbrMetallicRoughness',{}):
  raise ValueError('Bark diffuse texture did not export')
if saved:
 bpy.context.preferences.filepaths.save_version=0
 bpy.ops.wm.save_as_mainfile(filepath=str(saved[0].resolve()),compress=True)"},{"path":"app/CaptureScene.tsx","originalFileSha256":"9b701e28d259cb06a4a143f3f9d13c82eac9b873effd3cb6733fde1bb4b51987","lines":[69,94],"code":"    let comparison:THREE.Object3D|undefined;
